fun rational(n: Long, d: Long = 1): Rational {
    var p = n
    var q = d
    var a = abs(p)
    var b = q
    while (b != 0L) {
        val t = a % b
        a = b
        b = t
    }
    return Rational(p / a, q / a)
fun number(q: Rational) = Expr(5, q, "", emptyList())
fun num(p: Long, q: Long = 1) = number(rational(p, q))
fun num(p: Int) = num(p.toLong())
